function clearCpfError(){el("cpfError").hidden=true;el("firstCpf").removeAttribute("aria-invalid");el("firstCpf").style.removeProperty("border");}el("firstCpf").addEventListener("input",e=>{clearCpfError();const input=e.target;const before=input.value;const pos=input.selectionStart??before.length;const count=before.slice(0,pos).replace(/[^0-9]/g,"").length;const d=before.replace(/[^0-9]/g,"").slice(0,11);const formatted=d.replace(/^(\d{3})(\d)/,"$1.$2").replace(/^(\d{3}\.\d{3})(\d)/,"$1.$2").replace(/(\.\d{3})(\d{1,2})$/,"$1-$2");input.value=formatted;let cursor=0,n=0;while(cursor<formatted.length&&n<count){if(/[0-9]/.test(formatted[cursor]))n++;cursor++;}input.setSelectionRange(cursor,cursor);});el("cpfFirst").onsubmit=e=>{e.preventDefault();const d=el("firstCpf").value.replace(/[^0-9]/g,"");let valid=d.length===11&&new Set(d).size>1;if(valid){for(const n of [9,10]){let sum=0;for(let i=0;i<n;i++)sum+=Number(d[i])*(n+1-i);const rem=sum%11;if(Number(d[n])!==(rem<2?0:11-rem))valid=false;}}if(!valid){el("cpfError").hidden=false;el("firstCpf").setAttribute("aria-invalid","true");el("firstCpf").style.border="2px solid #dc2626";el("firstCpf").focus();status("Corrija o CPF para continuar.");return;}clearCpfError();el("cpfFirst").hidden=true;el("credentials").hidden=false;el("heading").textContent="Crie sua conta";el("intro").textContent="Informe seu e-mail e escolha uma senha.";el("reset").hidden=true;el("address").focus();status("Após confirmar seu e-mail, envie seus dados para aprovação.");};el("login").onclick=()=>mode(false);el("register").onclick=()=>mode(true);
