function inspectStatement(d){if(d?.statementSchema!==2||!Array.isArray(d.statementEntries))return {ok:false,reason:"Esquema ausente ou inválido"};let credit=0,debit=0;const ids=new Set();let repeated=0;for(const b of d.statementEntries){if(!b||!["credit","debit"].includes(b.type)||!Number.isSafeInteger(b.amountCents)||b.amountCents<0||typeof b.date!=="string"||!/^\d{4}-\d{2}-\d{2}$/.test(b.date)||!Number.isFinite(Date.parse(b.date))||new Date(b.date).toISOString().slice(0,10)!==b.date)return {ok:false,reason:"Lançamento inválido"};if(b.type==="credit")credit+=b.amountCents;else debit+=b.amountCents;if(!Number.isSafeInteger(credit)||!Number.isSafeInteger(debit))return {ok:false,reason:"Total fora do limite seguro"};if(typeof b.id==="string"&&b.id){if(ids.has(b.id))repeated++;ids.add(b.id);}}const t=d.statementTotalsCents;const mismatch=!!t&&(t.credit!==credit||t.debit!==debit);return {ok:!mismatch,reason:mismatch?"Totais importados divergentes":null,credit,debit,repeated,totalsAvailable:!!t};}
