 if(!panel.isConnected||actor!==auth.currentUser?.uid||epoch!==generation)return;
 const rows=snap.docs.map(d=>d.data()).sort((a,b)=>String(a.name||'').localeCompare(String(b.name||''),'pt-BR'));
